{ xi.item.BRONZE_DAGGER,       156, astralCandescence = false },\n            { xi.item.DAGGER,             2030, astralCandescence = true  },\n            { xi.item.SAPARA,              776, astralCandescence = false },\n            { xi.item.SCIMITAR,           4525, astralCandescence = false },\n            { xi.item.TULWAR,            38800, astralCandescence = true  },\n            { xi.item.TABAR,             66000, astralCandescence = false },\n            { xi.item.DARKSTEEL_TABAR,  124305, astralCandescence = true  },\n            { xi.item.BUTTERFLY_AXE,       672, astralCandescence = false },\n            { xi.item.GREATAXE,           4550, astralCandescence = true  },\n            { xi.item.BRONZE_ZAGHNAL,      344, astralCandescence = false },\n            { xi.item.ZAGHNAL,           12540, astralCandescence = true  },\n            { xi.item.ASH_CLUB,             72, astralCandescence = false },\n            { xi.item.CHESTNUT_CLUB,      1740, astralCandescence = true  },\n            { xi.item.ANGON,               238, astralCandescence = false },\n        }\n\n        player:showText(npc, zones[xi.zone.AHT_URHGAN_WHITEGATE].text.HAGAKOFF_SHOP_DIALOG)\n        xi.besieged.shop(player, stock)\n    end,\n})\n\n-- Mazween: Absorb-ACC requires WOTG\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.zones.Aht_Urhgan_Whitegate.npcs.Mazween.onTrigger', {\n    [xi.expansion.ABYSSEA] = function(player, npc)\n        local stock =\n        {\n            { xi.item.SCROLL_OF_SLEEPGA,      11200 },\n            { xi.item.SCROLL_OF_SLEEP_II,     18720 },\n            { xi.item.SCROLL_OF_POISON_II,    25200 },\n            { xi.item.SCROLL_OF_BIO_II,       14000 },\n            { xi.item.SCROLL_OF_POISONGA,      5160 },\n            { xi.item.SCROLL_OF_STONE_III,    19932 },\n            { xi.item.SCROLL_OF_WATER_III,    22682 },\n            { xi.item.SCROLL_OF_AERO_III,     27744 },\n            { xi.item.SCROLL_OF_FIRE_III,     33306 },\n            { xi.item.SCROLL_OF_BLIZZARD_III, 39368 },\n            { xi.item.SCROLL_OF_THUNDER_III,  45930 },\n            { xi.item.SCROLL_OF_ABSORB_TP,    27000 },\n            { xi.item.SCROLL_OF_DRAIN_II,     30780 },\n            { xi.item.SCROLL_OF_DREAD_SPIKES, 70560 },\n        }\n\n        if not xi.pre(xi.expansion.WOTG) then\n            table.insert(stock, { xi.item.SCROLL_OF_ABSORB_ACC, 44000 })\n        end\n\n        player:showText(npc, zones[xi.zone.AHT_URHGAN_WHITEGATE].text.MAZWEEN_SHOP_DIALOG)\n        xi.shop.general(player, stock)\n    end,\n})\n\n-- Khaf Jhifanm: Remove Empire Waystone from stock\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.zones.Aht_Urhgan_Whitegate.npcs.Khaf_Jhifanm.onTrigger', {\n    [xi.expansion.SOA] = function(player, npc)\n        local stock =\n        {\n            { xi.item.DRIED_DATE,                200 },\n            { xi.item.FLASK_OF_AYRAN,             800 },\n            { xi.item.BALIK_SANDVICI,            3750 },\n            { xi.item.BAG_OF_WILDGRASS_SEEDS,     320 },\n            { xi.item.SCROLL_OF_RAPTOR_MAZURKA,  4500 },\n        }\n\n        player:showText(npc, zones[xi.zone.AHT_URHGAN_WHITEGATE].text.KHAFJHIFANM_SHOP_DIALOG)\n        xi.shop.general(player, stock)\n    end,\n})\n"},["modules/era/lua/zones/aht_urhgan_whitegate/npcs/ghatsad.lua"]={["Path"]="modules/era/lua/zones/aht_urhgan_whitegate/npcs/ghatsad.lua",["SHA256"]="56d7a4f86e4b0e7fa088293e8fec092f7ba7db9e70292fa4fd40d425da142c69",["Text"]="-----------------------------------\n-- Choosing an Automaton Frame\n-- Restores the original frame materials for Valoredge X-900 and Sharpshot Z-500.\n-- Restores the JST midnight waits for Ghatsad to finish new automaton frames and heads.\n-- Ghatsad stops work on a head each midnight until he is given the day's Imperial Coffee.\n-- The March 26, 2015 version update replaced Tigerfangs with Patas and a Repeating\n-- Crossbow with a Heavy Crossbow.\n-- The June 7, 2016 version update shortened the frame wait to one Vana'diel day.\n-- The September 11, 2017 version update changed the head waits to count Vana'diel days.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/46531-Mar-26-2015-(JST)-Version-Update\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-- Source: https://forum.square-enix.com/ffxi/threads/53127-September.-11-2017-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/13124.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_choosing_an_automaton_frame', xi.pre(xi.expansion.ROV))\n\nlocal frameMaterialReplacements =\n{\n    [2] = { current = xi.item.PATAS,          original = xi.item.TIGERFANGS         },\n    [3] = { current = xi.item.HEAVY_CROSSBOW, original = xi.item.REPEATING_CROSSBOW },\n}\n\n-- Heads are built one work day at a time.\n-- A work day requires the day's coffee and completes when JST midnight passes.\n\nlocal function getOriginalFrameTrade(trade, replacement)\n    return\n    {\n        getItemQty = function(_, itemId)\n            return trade:getItemQty(itemId == replacement.current and replacement.original or itemId)\n        end,\n\n        getSlotCount = function()\n            return trade:getSlotCount()\n        end,\n    }\nend\n\n-- A fueled work day that reached midnight is complete.\nlocal function settleHeadWork(player)\n    local fueledUntil = player:getCharVar('[PUP]HeadFueled')\n\n    if fueledUntil ~= 0 and JstMidnight() > fueledUntil then\n        local daysRemaining = player:getCharVar('[PUP]HeadDaysRemaining') - 1\n\n        player:setCharVar('[PUP]HeadDaysRemaining', daysRemaining)\n        player:setCharVar('[PUP]HeadFueled', 0)\n\n        -- Finished. The base script's Vana'diel day timer no longer applies.\n        if\n            daysRemaining <= 0 and\n            player:getCharVar('PUP_AttachmentReady') > VanadielUniqueDay()\n        then\n            player:setCharVar('PUP_AttachmentReady', VanadielUniqueDay())\n        end\n    end\nend\n\nm:addOverride('xi.zones.Aht_Urhgan_Whitegate.npcs.Ghatsad.onTrade', function(player, npc, trade)\n    local attachmentStatus = player:getCharVar('PUP_AttachmentStatus')\n\n    local materialReplacement = frameMaterialReplacements[attachmentStatus]\n\n    if materialReplacement then\n        super(player, npc, getOriginalFrameTrade(trade, materialReplacement))\n        return\n    end\n\n    -- The day's coffee gets Ghatsad back to work on a head.\n    if attachmentStatus == 12 or attachmentStatus == 13 then\n        settleHeadWork(player)\n\n        if player:getCharVar('[PUP]HeadDaysRemaining') > 0 then\n            if\n                player:getCharVar('[PUP]HeadFueled') == 0 and\n                npcUtil.tradeMatches(trade, { { xi.item.CUP_OF_IMPERIAL_COFFEE, 1 } })\n            then\n                player:startEvent(904)\n            end\n\n            return\n        end\n    end\n\n    super(player, npc, trade)\n\n    -- The trade commissioned a head. The rolled wait becomes days of work.\n    local newStatus = player:getCharVar('PUP_AttachmentStatus')\n\n    if\n        newStatus ~= attachmentStatus and\n        (newStatus == 12 or newStatus == 13)\n    then\n        -- The commission day is worked for free.\n        player:setCharVar('[PUP]HeadDaysRemaining', player:getCharVar('PUP_AttachmentReady') - VanadielUniqueDay())\n        player:setCharVar('[PUP]HeadFueled', JstMidnight())\n    end\nend)\n\nm:addOverride('xi.zones.Aht_Urhgan_Whitegate.npcs.Ghatsad.onTrigger', function(player, npc)\n    local attachmentStatus = player:getCharVar('PUP_AttachmentStatus')\n\n    -- Paid in full for a frame. Ghatsad works on it until real midnight passes.\n    if attachmentStatus >= 8 and attachmentStatus <= 10 then\n        local completionTime = player:getCharVar('[PUP]FrameCompletion')\n\n        if completionTime ~= 0 then\n            if JstMidnight() <= completionTime then\n                player:startEvent(626)\n                return\n            end\n\n            -- Midnight has passed. The base script's Vana'diel day timer no longer applies.\n            player:setCharVar('[PUP]FrameCompletion', 0)\n\n            if player:getCharVar('PUP_AttachmentReady') > VanadielUniqueDay() then\n                player:setCharVar('PUP_AttachmentReady', VanadielUniqueDay())\n            end\n        end\n\n    -- Paid in full for a head.\n    elseif attachmentStatus == 12 or attachmentStatus == 13 then\n        settleHeadWork(player)\n\n        local daysRemaining = player:getCharVar('[PUP]HeadDaysRemaining')\n\n        if daysRemaining > 0 then\n            if player:getCharVar('[PUP]HeadFueled') ~= 0 then\n                player:startEvent(903, daysRemaining, 1)\n            else\n                -- Param 2 = 0 adds the drowsy dialogue. No work until he gets the day's coffee.\n                player:startEvent(903, daysRemaining, 0)\n            end\n\n            return\n        end\n    end\n\n    super(player, npc)\nend)\n\nm:addOverride('xi.zones.Aht_Urhgan_Whitegate.npcs.Ghatsad.onEventFinish', function(player, csid, option, npc)\n    super(player, csid, option, npc)\n\n    -- Frame commission accepted. It is finished once real midnight passes.\n    if csid == 625 then\n        player:setCharVar('[PUP]FrameCompletion', JstMidnight())\n\n    -- Coffee accepted. Ghatsad works until midnight.\n    -- Players already mid-wait when the module deployed keep the base coffee behavior.\n    elseif csid == 904 and player:getCharVar('[PUP]HeadDaysRemaining') > 0 then\n        player:setCharVar('[PUP]HeadFueled', JstMidnight())\n\n    -- Frame or head handed over.\n    elseif csid == 627 or csid == 905 then\n        player:setCharVar('[PUP]FrameCompletion', 0)\n        player:setCharVar('[PUP]HeadDaysRemaining', 0)\n        player:setCharVar('[PUP]HeadFueled', 0)\n    end\nend)\n"},["modules/era/lua/zones/bastok_markets/npcs/bastok_markets_vendors.lua"]={["Path"]="modules/era/lua/zones/bastok_markets/npcs/bastok_markets_vendors.lua",["SHA256"]="bb172121de03cba11c16779c0c4b81640d76f5b0b3d201224058f1aa54a43c86",["Text"]="-----------------------------------\n-- Bastok Markets Vendor Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('bastok_markets_vendors_adjust')\n\n-- Harmodios: Rework stock for in era items and conquest standing requirements\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.zones.Bastok_Markets.npcs.Harmodios.onTrigger', {\n    [xi.expansion.ROV] = function(player, npc)\n        local stock =\n        {\n            { xi.item.GEMSHORN,                    5159, 3 },\n            { xi.item.CORNETTE,                     244, 2 },\n            { xi.item.FLUTE,                         49, 3 },\n            { xi.item.PICCOLO,                     1090, 1 },\n            { xi.item.MAPLE_HARP,                    49, 2 },\n            { xi.item.SCROLL_OF_VITAL_ETUDE,      76800, 2 },\n            { xi.item.SCROLL_OF_SWIFT_ETUDE,      73600, 2 },\n            { xi.item.SCROLL_OF_SAGE_ETUDE,       70400, 2 },\n            { xi.item.SCROLL_OF_LOGICAL_ETUDE,    63000, 2 },\n            { xi.item.SCROLL_OF_BEWITCHING_ETUDE, 60000, 3 },\n            { xi.item.SCROLL_OF_HERCULEAN_ETUDE,  88400, 2 },\n            { xi.item.SCROLL_OF_UNCANNY_ETUDE,    85000, 2 },\n        }\n\n        player:showText(npc, zones[xi.zone.BASTOK_MARKETS].text.HARMODIOS_SHOP_DIALOG)\n        xi.shop.nation(player, stock, xi.nation.BASTOK)\n    end,\n})\n\n-- Ciqala: Rework inventory for era stock and conquest standing requirements\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.zones.Bastok_Markets.npcs.Ciqala.onTrigger', {\n    [xi.expansion.ABYSSEA] = function(player, npc)\n        local stock =\n        {\n            { x