xi.zones.Lower_Jeuno.npcs.Ghebi_Damomohe.onEventFinish', {\n    [xi.expansion.ROV] = function(player, csid, option, npc)\n        if csid == 106 and option == 0 then\n            local stock =\n            {\n                { xi.item.RICE_BALL,        160 },\n                { xi.item.EEL_KABOB,       3000 },\n                { xi.item.GARLIC_CRACKER,     4 },\n            }\n\n            xi.shop.general(player, stock, xi.fameArea.NORG)\n        else\n            super(player, csid, option, npc)\n        end\n    end,\n})\n"},["modules/phoenix/lua/Quests/A_Foremans_Best_Friend.lua"]={["Path"]="modules/phoenix/lua/Quests/A_Foremans_Best_Friend.lua",["SHA256"]="c7f40795fd60bb2758465f30f296d775c291a89ba4559d96b85e6366dc588156",["Text"]="-----------------------------------\n-- Module to remove the exp compensation given by 'A Foreman's Best Friend' when the\n-- player already holds the map key item.\n-- Exp was added in 2013 so it is removed here.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_a_foremans_best_friend', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/bastok/A_Foremans_Best_Friend', function(quest)\n        quest.sections[2][xi.zone.PORT_BASTOK].onEventFinish[112] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:tradeComplete()\n                if not player:hasKeyItem(xi.keyItem.MAP_OF_THE_GUSGEN_MINES) then\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_THE_GUSGEN_MINES)\n                end\n            end\n        end\n    end)\nend)\n"},["modules/phoenix/lua/Quests/A_Smudge_on_Ones_Record.lua"]={["Path"]="modules/phoenix/lua/Quests/A_Smudge_on_Ones_Record.lua",["SHA256"]="cac56ec29bc24f8a976fbc6bf820043d2d0539913d24e937ea31a48028e9019e",["Text"]="-----------------------------------\n-- Module to remove exp and fame from 'A Smudge on One's Record' quest reward, and\n-- correct the gil reward to 3,000.\n-- Gil and exp were added to the quest reward in 2013 so exp is removed and gil corrected here.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_a_smudge_on_ones_record', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/windurst/A_Smudge_on_Ones_Record', function(quest)\n        quest.reward = {\n            keyItem = xi.keyItem.MAP_OF_FEIYIN,\n            gil     = 3000,\n        }\n    end)\nend)\n"},["modules/phoenix/lua/Quests/Exit_the_Gambler.lua"]={["Path"]="modules/phoenix/lua/Quests/Exit_the_Gambler.lua",["SHA256"]="efceb420fa22eacf3875f7891ceac5e4d996485005a0e1b0ee08c497391b7ebd",["Text"]="-----------------------------------\n-- Module to remove exp, gil, and fame from 'Exit the Gambler' quest reward.\n-- Gil and exp were added to the quest reward in 2013 so they are removed here.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_exit_the_gambler', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/Exit_the_Gambler', function(quest)\n        quest.reward = {\n            keyItem = xi.keyItem.MAP_OF_KING_RANPERRES_TOMB,\n            title   = xi.title.DAYBREAK_GAMBLER,\n        }\n    end)\nend)\n"},["modules/phoenix/lua/Quests/Glyph_Hanger.lua"]={["Path"]="modules/phoenix/lua/Quests/Glyph_Hanger.lua",["SHA256"]="9fe45f48cfe4c60ab04f50c77f2143962141dd341de3f243f62152f92672031e",["Text"]="-----------------------------------\n-- Module to remove exp and fame from 'Glyph Hanger' quest reward.\n-- Exp was added to the quest reward in 2013 so it is removed here.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_glyph_hanger', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/windurst/Glyph_Hanger', function(quest)\n        quest.reward = {\n            keyItem = xi.keyItem.MAP_OF_THE_HORUTOTO_RUINS,\n        }\n    end)\nend)\n"},["modules/phoenix/lua/Quests/Go_Go_Gobmuffin.lua"]={["Path"]="modules/phoenix/lua/Quests/Go_Go_Gobmuffin.lua",["SHA256"]="1064bc9ac7b5a9ebc56593298a1e7172d5b7fb447d19a649845710c3ba1ddc72",["Text"]="-----------------------------------\n-- Module to remove exp and gil from 'Go Go Gobmuffin' quest reward.\n-- Gil and exp were added to the quest reward in 2013 so they are removed here.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_go_go_gobmuffin', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/Go_Go_Gobmuffin', function(quest)\n        quest.reward = {\n            keyItem = xi.keyItem.MAP_OF_CAPE_RIVERNE,\n        }\n    end)\nend)\n"},["modules/phoenix/lua/Quests/Lost_in_Translocation.lua"]={["Path"]="modules/phoenix/lua/Quests/Lost_in_Translocation.lua",["SHA256"]="12111559a6813c75b42a52f99af4b3775ca6dfb867ce5905a8de648d21ce47f0",["Text"]="-----------------------------------\n-- Module to remove exp and gil from 'Lost in Translocation' quest reward.\n-- Gil and exp were added to the quest reward in 2013 so they are removed here.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_lost_in_translocation', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modify